UPDATE courses SET
    course_description = '<h4>Overview</h4><p>With the Bachelor of Engineering Honours (Environmental Engineering), gain expertise in sustainable energy, water supply, waste treatment, and environmental monitoring. Develop and design sustainable solutions for complex environmental issues. </p> <p>Acquire knowledge of environmental systems through the study of chemical, civil and mechanical engineering and learn how to reduce the footprint of engineering processes. Choose to specialise in advanced water treatment and purification technologies, energy optimisation, or geotechnical engineering.</p>',
    course_duration_per_week = 208,
    offshore_tuition_fee = 60600,
    onshore_tuition_fee = 8796,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '<table><tbody><tr><td><strong>English Proficiency</strong></td><td><ul><li>TOEFL - IBT score: A minimum result of 85 overall including a minimum result of 17 in Reading, Listening and Speaking and 19 in Writing</li><li>IELTS score: A minimum result of 6.5 overall and a minimum result of 6.0 in each band</li><li>Pearsons Test of English: A minimum result of 64 overall and a minimum result of 60 in each band</li></ul></td></tr></tbody></table>',
