UPDATE courses SET
    course_description = '<h4>Overview</h4><p>The Bachelor of Languages (Honours) program enhances the information and digital literacy skills gained in the <a href="/content/courses/courses/uc/bachelor-of-languages.html">Bachelor of Languages</a>. It will enable you to conduct research and complete a thesis aligned with a language major from your bachelor''s degree.</p> <p>Honours is for those aiming to launch a career as an academic or professional researcher. During the honours year, you will engage in seminar classes and work on a short thesis, conducting an independent research project under the guidance of an expert academic staff member in your field.</p>',
    course_duration_per_week = 52,
    offshore_tuition_fee = 52500,
    onshore_tuition_fee = 17399,
