    offshore_tuition_fee = 27050,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '<table><tbody><tr><td><strong>Academic Requirements</strong></td><td><p>Admission to candidature requires a bachelor''s degree from the University of Sydney or equivalent qualification.</p> </td></tr><tr><td><strong>English Proficiency</strong></td><td><ul><li>TOEFL - IBT score: A minimum result of 85 overall including a minimum result of 17 in Reading, Listening and Speaking and 19 in Writing</li><li>IELTS score: A minimum result of 6.5 overall and a minimum result of 6.0 in each band</li><li>Pearsons Test of English: A minimum result of 64 overall and a minimum result of 60 in each band</li></ul></td></tr></tbody></table>',
    apply_form = 'https://www.sydney.edu.au/courses/courses/pc/graduate-certificate-in-human-and-community-services.html',
    updated_at = NOW()
WHERE cricos_course_code = '068550G';

